#!/usr/bin/env node
/**
 * Generates every color artifact from the single list in src/app/registry/colorTokens.ts:
 *   - src/styles/colors.generated.css            web CSS custom properties (light and dark)
 *   - native-spike/src/universal/sourcePalette.json   resolved values read by the React Native demo
 *
 * Usage: node scripts/generate-colors.mjs [--check]
 *   --check   write nothing; exit 1 if a generated file differs from the source (npm run audit:colors)
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const check = process.argv.includes('--check')
const { COLOR_TOKENS, resolveColorToken } = await import(pathToFileURL(path.join(root, 'src/app/registry/colorTokens.ts')).href)

const byName = new Map()
for (const token of COLOR_TOKENS) {
  if (byName.has(token.name)) throw new Error(`Duplicate color token ${token.name}`)
  byName.set(token.name, token)
}

// Alias resolution is shared with the app (src/app/registry/colorTokens.ts).
const resolveLight = (name) => resolveColorToken(name, 'light')
const resolveDark = (name) => resolveColorToken(name, 'dark')

// 1. Web CSS.
const block = (selectors, tokens, pick) =>
  `${selectors} {\n${tokens
    .filter((t) => pick(t) !== undefined)
    .map((t) => `  ${t.name}: ${pick(t)};`)
    .join('\n')}\n}\n`
const css =
  `/* Generated by scripts/generate-colors.mjs from src/app/registry/colorTokens.ts. Do not edit. */\n\n` +
  block(':root,\n[data-uc-theme="light"]', COLOR_TOKENS, (t) => t.light) +
  '\n' +
  block('.dark,\n[data-uc-theme="dark"]', COLOR_TOKENS, (t) => t.dark)

// 2. React Native palette: resolved values, only the --uc- colors the demo reads through sourceColor().
const nativeNames = COLOR_TOKENS.filter((t) => t.name.startsWith('--uc-') && t.light !== undefined).map((t) => t.name)
const palette = { light: {}, dark: {} }
for (const name of nativeNames) {
  palette.light[name] = resolveLight(name)
  palette.dark[name] = resolveDark(name)
}
const json = JSON.stringify(palette, null, 2) + '\n'

const outputs = [
  ['src/styles/colors.generated.css', css],
  ['native-spike/src/universal/sourcePalette.json', json],
]
let stale = false
for (const [file, content] of outputs) {
  const target = path.join(root, file)
  const current = existsSync(target) ? readFileSync(target, 'utf8') : null
  if (check) {
    if (current !== content) {
      console.error(`Out of date: ${file}. Run npm run generate:colors.`)
      stale = true
    }
  } else if (current !== content) {
    writeFileSync(target, content)
    console.log(`Wrote ${file}`)
  }
}
if (check) {
  if (stale) process.exit(1)
  console.log(`Colors in sync: ${COLOR_TOKENS.length} tokens, ${nativeNames.length} in the native palette.`)
} else {
  console.log(`${COLOR_TOKENS.length} tokens, ${nativeNames.length} in the native palette.`)
}
